contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: caller address (ignored since msg.sender is this contract), recipient, and an amount to fund C
    function run(address payable recipient, uint256 fundAmount, address possibleOwner) public payable {
        require(address(this).balance >= fundAmount);

        // Deploy-time owner was provided when c was constructed by the checker; we can observe it
        address ownerBefore = c.owner();

        // Fund the contract c by sending Ether from this test contract
        // ensure we have enough balance then send
        (bool sent,) = address(c).call{value: fundAmount}("");
        // call to fallback may succeed or fail depending on fundAmount/logic; require it succeeded to set up balance
        require(sent);

        // record c balance before withdraw attempt
        uint256 balBefore = address(c).balance;
        // record test contract balance before
        uint256 ourBefore = address(this).balance;

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;
        uint256 ourAfter = address(this).balance;

        // General rule:
        // If the stored owner equals this contract (the caller), withdrawAll must not revert and must move the entire c balance to the recipient (so c balance goes to 0 and recipient's balance increases by balBefore).
        // If the stored owner is any other address, withdrawAll must revert (so balances unchanged).
        // We can only observe recipient via address(this).balance if recipient == address(this). To express the rule generally using observable values:
        // - If ownerBefore == address(this): reverted == false, balAfter == 0, and ourAfter == ourBefore + balBefore when recipient == payable(address(this)).
        // - If ownerBefore != address(this): reverted == true and balAfter == balBefore and ourAfter == ourBefore.

        // Encode the above as a single assert combining cases. Note: when recipient != address(this) we cannot observe recipient's balance change, so we only assert c.balance behavior and revert behavior.
        if (ownerBefore == address(this)) {
            // must have succeeded and contract drained
            assert(!reverted && balAfter == 0 && (recipient == payable(address(this)) ? ourAfter == ourBefore + balBefore : true));
        } else {
            // must have reverted and nothing changed
            assert(reverted && balAfter == balBefore && ourAfter == ourBefore);
        }
    }

    // allow receiving Ether when c.transfer sends to this contract
    receive() external payable { }
}

