contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: takes caller (attempting withdraw) and recipient and an amount to fund C.
    function run(address caller, address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // fund the contract C by sending Ether from this contract
        // Note: address(this).balance check above ensures we have funds
        (bool sent,) = address(c).call{value: fundAmount}("");
        // funding via fallback should succeed (fallback is payable)
        require(sent);

        // read observable before-values
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // decide caller behavior: we simulate calls from either owner or non-owner by using two branches
        // We cannot change msg.sender of c calls here, but the InvMutTest contract is the msg.sender for external calls.
        // To simulate different callers, we rely on the provided `caller` parameter by requiring it equals owner or not,
        // and then using the rule expressed over that relation. We perform the withdrawAll call from this contract,
        // which will only succeed if this contract equals owner; thus to exercise both cases the checker will pick inputs accordingly.

        // Make the withdrawAll call from this contract (actual msg.sender = address(this)).
        bool didRevert;
        try c.withdrawAll(recipient) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // read after-values
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        // The general rule to assert (relates owner equality and effects):
        // If this contract is the owner, withdrawAll must not revert, transfer all Ether out of C to recipient (so balanceAfter == 0),
        // and owner remains unchanged. If this contract is not the owner, withdrawAll must revert and balance unchanged and owner unchanged.
        bool thisIsOwner = (address(this) == ownerBefore);

        assert(
            // owner never changes
            ownerAfter == ownerBefore
            && (
                // case: this contract is owner -> call should not revert and contract balance becomes zero and recipient got funds
                (thisIsOwner
                    ? (
                        didRevert == false
                        && balanceAfter == 0
                        && balanceBefore > 0 // if there was value to withdraw, ensure it was positive
                    )
                    // case: this contract not owner -> call must revert and balance unchanged
                    : (didRevert == true && balanceAfter == balanceBefore)
                )
            )
        );
    }

    // allow receiving Ether when test contract gets the withdrawn funds
    receive() external payable {}
}

