contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes: caller (address) to set as owner when constructing C was done by test harness;
    // amount to send into C before withdraw; and a recipient to receive withdrawn funds.
    // We cannot redeploy C here; the harness deploys a fresh C. We only interact via c.
    function run(address caller, uint256 depositAmount, address payable recipient) public payable {
        require(true);
        // Precondition: ensure this contract has enough balance if we will forward Ether into c.
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
            // send Ether to c using fallback to fund it
            (bool sent, ) = address(c).call{value: depositAmount}("");
            require(sent, "funding call failed");
        }

        // Observe balances before calling withdrawAll
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        address ownerAddr = c.owner();

        bool reverted;
        // Try to call withdrawAll as if from `caller`. We simulate calls from other addresses by
        // checking two cases: when caller equals owner (this contract must be owner to succeed),
        // but invoker of c is always this contract; so we only can call and success depends on
        // whether c.owner() == address(this). To exercise both behaviors, we branch on equality.
        if (caller == ownerAddr) {
            // We require the caller parameter to equal the actual owner; in that case the withdrawAll
            // call (made by this contract) should succeed and transfer all Ether to recipient.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After successful withdraw by owner, contract balance should be zero and recipient increased by beforeC
            assert(reverted == false && address(c).balance == 0 && recipient.balance == beforeRecipient + beforeC);
        } else {
            // If caller != owner, then invoking withdrawAll from this contract should revert (since msg.sender != owner)
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After a failed withdraw, contract balance must be unchanged and recipient untouched
            assert(reverted == true && address(c).balance == beforeC && recipient.balance == beforeRecipient);
        }
    }

    receive() external payable { }
}

