contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The single public test function: caller is this contract when interacting with c.
    // params: recipient to withdraw to, amount to fund c with, and a boolean chooseOwnerCall
    // If chooseOwnerCall==true we attempt withdrawAll from the owner address by first
    // deploying a call that simulates owner (here we cannot change msg.sender), so instead
    // we model two cases: when this contract is the owner (constructor of c set owner to this),
    // and when it is not. The checker deploys c fresh and supplied into constructor; we just
    // observe c.owner() and behave accordingly.
    function run(address payable recipient, uint256 amount, bool attemptWithdraw) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund c");

        // Fund c with Ether so there's something to withdraw.
        // Sending Ether to c uses the fallback payable.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // Read owner and c balance before withdraw attempt
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        if (attemptWithdraw) {
            // Try to withdrawAll to recipient and capture whether it reverts.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If we don't attempt withdraw, mark reverted = true to make assertion meaningful
            reverted = true;
        }

        // After attempted call, read owner and balances
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        /* General rule to assert:
           - If caller (this contract) is the owner, withdrawAll should not revert and all funds move from c to recipient.
           - If caller is not the owner, withdrawAll must revert and c's balance and owner must be unchanged.

           We express this with a single assert combining both cases. We use observable public fields only.
        */
        assert(
            // If we did not attempt withdraw, no state change should have happened
            (!attemptWithdraw && ownerBefore == ownerAfter && balanceBefore == balanceAfter)
            ||
            // If we attempted withdraw and this contract is the owner: must not revert, c balance becomes 0,
            // and either recipient received funds (observed indirectly if recipient==address(this) by thisBalanceAfter)
            // or if recipient is external we at least require c.balance decreased by balanceBefore when owner called.
            (attemptWithdraw && ownerBefore == address(this) && reverted == false && ownerBefore == ownerAfter && balanceAfter <= balanceBefore && balanceAfter == 0)
            ||
            // If we attempted withdraw and this contract is NOT the owner: it must have reverted and nothing changed on c.
            (attemptWithdraw && ownerBefore != address(this) && reverted == true && ownerBefore == ownerAfter && balanceBefore == balanceAfter)
        );
    }

    // Allow receiving Ether when recipient==address(this)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. Params: recipient to withdraw to, amount to fund C with, and a flag attemptWithdraw.
    function run(address payable recipient, uint256 amount, bool attemptWithdraw) public payable {
        // If we plan to fund C, require this contract has enough balance.
        require(address(this).balance >= amount, "insufficient balance to fund");

        // Fund C so there is something to withdraw. This is a top-level external call.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // Observe pre-call public state
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // Perform the withdraw attempt as a top-level call and capture whether it reverted.
        bool reverted;
        if (attemptWithdraw) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If not attempting withdraw, set reverted=false but make no call.
            reverted = false;
        }

        // Observe post-call public state
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;

        // General invariant:
        // - If this contract is the owner and we attempted withdraw, the call must not revert and C's balance becomes 0 and owner unchanged.
        // - If this contract is not the owner and we attempted withdraw, the call must revert and C's owner and balance remain unchanged.
        // - If we did not attempt withdraw, C's owner and balance remain unchanged.
        assert(
            // not attempting withdraw -> no changes to C
            (!attemptWithdraw && ownerBefore == ownerAfter && balanceBefore == balanceAfter)
            ||
            // attempted withdraw and this contract is owner -> must not revert, owner unchanged, balance zero
            (attemptWithdraw && ownerBefore == address(this) && reverted == false && ownerBefore == ownerAfter && balanceAfter == 0)
            ||
            // attempted withdraw and this contract not owner -> must revert, owner and balance unchanged
            (attemptWithdraw && ownerBefore != address(this) && reverted == true && ownerBefore == ownerAfter && balanceBefore == balanceAfter)
        );
    }

    // allow receiving Ether when testing transfers to this contract
    receive() external payable {}
}

