contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // run takes caller (attempting withdraw), ownerCandidate (to set as owner at construction time via c deployed externally),
    // recipient to receive funds, and amount to send to c before withdraw.
    function run(address caller, address recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Precondition: c was deployed with some owner (unknown here). We observe owner via public getter.
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // Fund the contract c by sending Ether from this test contract to c.
        // Must ensure we have enough balance; caller provides amount param and we required above.
        (bool sent,) = address(c).call{value: amount}("\x00");
        // funding might succeed or fail depending on fallback payable; record new balance
        uint256 balanceAfterFund = address(c).balance;

        // Decide who will attempt withdraw: we simulate calls by using this contract as msg.sender
        // To simulate different callers, we rely on c.owner() getter to determine allowed behavior.
        // If caller equals ownerBefore, this contract acting as caller should behave like owner only if ownerBefore == address(this).
        // Instead, to capture property for both cases, we'll attempt withdraw and observe whether it reverts.

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the withdraw attempt, observe owner (should be unchanged) and contract balance and this contract balance.
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        // General rule to assert:
        // 1) c.owner() never changes due to withdrawAll
        // 2) If the call did not revert, then entire contract balanceBefore+funding was transferred out to recipient (so c.balance == 0)
        // 3) If the call reverted, contract balance remains as before the withdraw attempt (no Ether drained by failed call)
        // We cannot observe recipient's balance directly, but we can observe that c's balance becomes zero on success.

        assert(
            ownerBefore == ownerAfter
            && (reverted ? balanceAfter == balanceAfterFund : balanceAfter == 0)
        );
    }

    receive() external payable { }
}

