contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params are potential owner, caller (ignored since calls originate from this contract), recipient, and an amount to fund C
    function run(address _owner, address payable _recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Deploy-time owner is already set by the checker when constructing C; here we simulate funding C
        // Send Ether to C so it has a balance to withdraw
        (bool sent,) = address(c).call{value: amount}("\x00");
        // call may succeed or not; we don't require it but proceed

        // read before-values
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = _recipient.balance;
        address owner = c.owner();

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = _recipient.balance;

        // General rule:
        // If the caller (this contract) is the owner, withdrawAll must not revert and must transfer entire balance to recipient (so c.balance becomes 0 and recipient balance increases by beforeC).
        // If the caller is not the owner, withdrawAll must revert and balances unchanged.
        // Note: this contract's address is the caller; so compare owner to address(this).
        if (owner == address(this)) {
            // If owner, withdrawAll should succeed and take all Ether from c
            assert(!reverted && afterC == 0 && afterRecipient == beforeRecipient + beforeC);
        } else {
            // If not owner, withdrawAll should revert and leave balances unchanged
            assert(reverted && afterC == beforeC && afterRecipient == beforeRecipient);
        }
    }

    receive() external payable {}
}

