contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes: owner address to initialize C with (must not be zero to be meaningful),
    // recipient to receive funds, and an amount to fund C before withdrawal.
    function run(address ownerAddr, address payable recipient, uint256 fundAmount) public payable {
        require(ownerAddr != address(0));
        // Fund this test contract so it can forward Ether to c when needed
        require(address(this).balance >= fundAmount);

        // Deploying contract c already happened outside; we must interact only via its interface.
        // First, check the declared owner of c (public getter)
        address declaredOwner = c.owner();

        // Send fundAmount to c so it has a balance to withdraw
        // Use low-level call via payable(address(c)).call{value: fundAmount}(""); but we must interact only via c's public/external surface.
        // c has a payable fallback, so calling with value will increase address(c).balance.
        // Ensure we have the funds
        require(address(this).balance >= fundAmount);
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        // Read balance before attempting withdraw
        uint256 beforeBalC = address(c).balance;
        uint256 beforeBalRecipient = recipient.balance;

        // Attempt withdraw as owner or as non-owner depending on declaredOwner matching provided ownerAddr.
        bool reverted;
        if (declaredOwner == ownerAddr) {
            // If this InvMutTest is the owner via the provided ownerAddr? We cannot change msg.sender for calls; msg.sender will be this contract.
            // The contract C was deployed fresh by the harness; its owner is whatever was passed at deployment. We only observe declaredOwner and use it to decide expected behavior.
        }

        // Make the call to withdrawAll from this contract (msg.sender == address(this))
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalC = address(c).balance;
        uint256 afterBalRecipient = recipient.balance;

        // General rule:
        // If this contract (address(this)) is the owner (declaredOwner == address(this)), then withdrawAll must succeed (not revert),
        // C's balance must become zero, and recipient's balance must increase by beforeBalC.
        // Otherwise (caller not owner), withdrawAll must revert and balances must be unchanged.
        if (declaredOwner == address(this)) {
            assert(!reverted && afterBalC == 0 && afterBalRecipient == beforeBalRecipient + beforeBalC);
        } else {
            assert(reverted && afterBalC == beforeBalC && afterBalRecipient == beforeBalRecipient);
        }
    }

    // Allow receiving ETH so run can be funded
    receive() external payable { }
}
